WITH (SELECT mapFromArrays(groupArray(id), groupArray(name)) FROM (SELECT id, any(name) AS name FROM item_names WHERE id IN (SELECT arrayJoin(item_ids) FROM npc_trades WHERE zone_id = {zone:Int64}) GROUP BY id)) AS names, e AS (SELECT *, ifNull(npc_name, '') AS name, coalesce(gil, 0) AS g, if(event_id IS NULL, if(message IS NULL, 'nothing', 'message ' || toString(message)), 'event ' || toString(event_id)) AS answer FROM (SELECT * FROM npc_trades WHERE zone_id = {zone:Int64} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged'))), a AS (SELECT name, item_ids, quantities, g, answer AS v, sum(n) AS k, argMax((capture_id, ts_ms), ts_ms) AS seen FROM e GROUP BY name, item_ids, quantities, g, v), c AS (SELECT name, item_ids, quantities, g, uniqExact(capture_id) AS captures FROM e GROUP BY name, item_ids, quantities, g) SELECT a.name AS npc_name, a.item_ids AS items, arrayMap(x -> if(x IS NULL, NULL, names[toInt64(assumeNotNull(x))]), a.item_ids) AS item_names, a.quantities AS quantities, a.g AS gil, sum(a.k) AS n, any(c.captures) AS captures, arraySlice(arrayReverseSort(t -> t.k, groupArray((v, k, seen))), 1, 10) AS answers FROM a LEFT JOIN c USING (name, item_ids, quantities, g) GROUP BY a.name, a.item_ids, a.quantities, a.g ORDER BY npc_name, n DESC
